        msgid: "old",
        msgstr: "régi",
        references: [],
        flags: [],
        fuzzy: false,
        obsolete: true,
      },
    ];
    const serialized = serializePo(entries);
    expect(parsePo(serialized)).toEqual(entries);
  });
});
